/// One straight-line piece of an envelope: `from` at `start`, reaching `to`
/// at `start + duration`. The field names are the §7.2 JSON keys.
#[derive(Debug, Clone, Copy, PartialEq, Serialize)]
pub struct Ramp {
    pub start: Ticks,
    pub duration: Ticks,
    pub from: f64,
    pub to: f64,
}

