/// file carries it, not through `set_track`, so the fixture says nothing
/// about the op.
fn nest_beside_a_track(solo: &[u32]) -> Handle {
    let with = |id: u32| {
        let mut track = track(id);
        if solo.contains(&id) {
            track["solo"] = json!(true);
        }
        track
    };
    Handle::from_value(&project(
