    // nest's track 8 is silenced, clip 9 plays, and the timeline's track 3
    // — not in that container — is untouched. Every segment stays.
    let plan = nest_beside_a_track(&[7]).plan();
    assert_eq!(array(&plan, "/audio_tracks").len(), 3);
