//! Spike S3, question 1: which timeline tracks one composition audio track's
//! segments come from, read off the plan the 9e47f56 core emits. Scratch only.

mod common;

use serde_json::{json, Value};

use common::{array, int, Handle};

const SEC: i64 = 600_000;

fn media(id: u32) -> Value {
    json!({
        "id": id, "path": format!("/fixtures/{id}.mov"), "kind": "video",
        "duration": 60 * SEC, "width": 1920, "height": 1080, "fps": [30, 1],
        "has_video": true, "has_audio": true
    })
}
fn track(id: u32) -> Value {
    json!({ "id": id, "name": format!("Track {id}") })
}
fn clip(id: u32, on: u32, start: i64, duration: i64) -> Value {
    json!({
        "id": id, "track": on, "start": start, "duration": duration,
        "source": { "kind": "media", "media": 1, "in": 0 },
        "video": {}, "audio": {}
    })
}
fn nest_clip(id: u32, on: u32, start: i64, duration: i64, shows: u32) -> Value {
    json!({
        "id": id, "track": on, "start": start, "duration": duration,
        "source": { "kind": "nest", "project": shows }, "video": {}
    })
}
fn nest(id: u32, tracks: Vec<Value>, clips: Vec<Value>) -> Value {
    json!({ "id": id, "name": format!("Nest {id}"), "width": 1920, "height": 1080,
            "tracks": tracks, "clips": clips })
}
fn project(tracks: Vec<Value>, clips: Vec<Value>, nests: Vec<Value>, next_id: u32) -> Value {
    json!({
        "version": 2,
        "canvas": { "width": 1920, "height": 1080, "fps": [30, 1],
                    "background": [0.0, 0.0, 0.0, 1.0],
                    "fit_new_clips": true, "timecode_frames": true },
        "media": [media(1)], "tracks": tracks, "clips": clips, "markers": [],
        "next_id": next_id, "nests": nests
    })
}

fn dump(name: &str, plan: &Value) -> Vec<Vec<i64>> {
    let mut out = Vec::new();
    println!("--- {name}");
    for comp in array(plan, "/audio_tracks") {
        let clips: Vec<i64> = array(comp, "/segments").iter().map(|s| int(s, "/clip")).collect();
        let spans: Vec<String> = array(comp, "/segments")
            .iter()
            .map(|s| format!("clip {} @ {}..{} s", int(s, "/clip"),
                int(s, "/start") as f64 / SEC as f64,
                (int(s, "/start") + int(s, "/duration")) as f64 / SEC as f64))
            .collect();
        println!("  comp audio track {}: {}", int(comp, "/id"), spans.join(", "));
        out.push(clips);
    }
    out
}

#[test]
fn s3_mapping() {
    // A: one timeline track (2) holding a nest clip (4) over 0-2 s; the nest (5) has two
    // inner tracks, 7 (clip 9 at 0-1 s) and 8 (clip 10 at 1-2 s).
    let a = Handle::from_value(&project(
        vec![track(2)],
        vec![nest_clip(4, 2, 0, 2 * SEC, 5)],
        vec![nest(5, vec![track(7), track(8)],
                  vec![clip(9, 7, 0, SEC), clip(10, 8, SEC, SEC)])],
        11,
    ));
    let pa = dump("A: nest, inner tracks 7 (clip 9, 0-1 s) and 8 (clip 10, 1-2 s), sequential", &a.plan());

    // B: track 2 holds that nest clip (0-2 s) and a top-level clip 11 at 2-3 s; track 3 holds
    // clip 12 at 3-4 s (sequential with everything on track 2).
    let b = Handle::from_value(&project(
        vec![track(2), track(3)],
        vec![nest_clip(4, 2, 0, 2 * SEC, 5), clip(11, 2, 2 * SEC, SEC), clip(12, 3, 3 * SEC, SEC)],
        vec![nest(5, vec![track(7), track(8)],
                  vec![clip(9, 7, 0, SEC), clip(10, 8, SEC, SEC)])],
        13,
