// Integrated (ungated mean) loudness both ways.
func meanLUFS(_ x: [[Float]]) -> Double {
    let kl = kWeighted(x[0]), kr = kWeighted(x[1])
    var s = 0.0
    for i in 0..<kl.count { s += kl[i] * kl[i] + kr[i] * kr[i] }
    return -0.691 + 10 * log10(s / Double(kl.count))
}
