            var p: Float = 0
            for i in start..<(start + 4096) { p = max(p, abs(r.store[0][i]), abs(r.store[1][i])) }
            sumPeak += p * envelope(specs[k].legs, at: Double(start) / 48000)
        }
        var mixPeak: Float = 0
        for i in start..<(start + 4096) { mixPeak = max(mixPeak, abs(truth[0][i]), abs(truth[1][i])) }
